7	use App\Inventory\Application\EventHandler\ReleaseReservationsHandler;
8	use App\Inventory\Domain\Repository\StockItemRepository;
9	use App\Ordering\Domain\Model\Order;
10	use App\Ordering\Domain\Repository\OrderRepository;
11	use App\Ordering\Domain\ValueObject\CustomerId;
12	use App\Ordering\Domain\ValueObject\OrderId;
13	use App\Ordering\Domain\ValueObject\ProductId;
14	use App\SharedKernel\Domain\Currency;
15	use App\SharedKernel\Domain\Money;
16	use App\Tests\Support\Catalog;
17	use App\Tests\Support\TestDatabase;
18	use Doctrine\DBAL\Connection;
19	use PHPUnit\Framework\Attributes\CoversClass;
20	use PHPUnit\Framework\Attributes\Test;
21	use Symfony\Bundle\FrameworkBundle\Test\KernelTestCase;
22	
23	#[CoversClass(ReleaseReservationsHandler::class)]
24	final class ReleaseReservationsTest extends KernelTestCase
25	{
26	    protected function setUp(): void
27	    {
28	        TestDatabase::reset();
29	        self::bootKernel();
30	        Catalog::seed(self::getContainer()->get(Connection::class));
31	    }
32	
33	    #[Test]
34	    public function cancelledOrderReleasesItsReservations(): void
35	    {
36	        $orders = self::getContainer()->get(OrderRepository::class);
37	        $stockItems = self::getContainer()->get(StockItemRepository::class);
38	        $keyboard = ProductId::fromString(Catalog::KEYBOARD);
39	
40	        $order = Order::place(OrderId::generate(), CustomerId::generate());
41	        $order->addItem($keyboard, 3, new Money(500_00, Currency::CZK));
42	        $orders->save($order);
43	        self::assertSame(7, $stockItems->get($keyboard)->available());
44	
45	        $order->cancel('customer request', new \DateTimeImmutable());
46	        $orders->save($order);
47	
48	        self::assertSame(10, $stockItems->get($keyboard)->available());
49	    }
50	}
